CREATE TABLE IF NOT EXISTS campsites (id BIGSERIAL PRIMARY KEY, uuid uuid NOT NULL, "name" TEXT NOT NULL, "location" GEOGRAPHY(PointZ, 4326) NOT NULL, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campsitevisits (id BIGSERIAL PRIMARY KEY, uuid uuid NOT NULL, description TEXT NOT NULL, date_arrived DATE NOT NULL, date_left DATE NOT NULL, price_cents INT NULL, person_count INT NULL, tent_count INT NULL, car_count INT NULL, van_count INT NULL, campsite BIGINT NOT NULL, CONSTRAINT fk_campsitevisits_campsite__id FOREIGN KEY (campsite) REFERENCES campsites(id) ON DELETE RESTRICT ON UPDATE RESTRICT);
CREATE SEQUENCE IF NOT EXISTS Campsites_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS CampsiteVisits_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
